// development maintains only zh-CN + en). Missing keys fall back to en at lookup time
// (i18n/index.tsx); `...modulesEn` first keeps every key present, the entries below override.
//
// Glossario (scelte consolidate; termini introdotti con il batch 2026-10-15 marcati «nuovo»):
// agent→agente, turn→turno, thread→thread, runtime→runtime, host→host, peer→peer, profile→profilo,
// delegation→delega, queue→coda, approvals→approvazioni, alarms→promemoria, notes→note,
// bookmarks→segnalibri, side chat→chat laterale, effort→impegno, usage→utilizzo, quota→quota,
// preset→preset, job→job, workflow→workflow, bus→bus, relay→relay, release→release (nuovo),
// preflight→preflight (nuovo), roll back→ripristino/ripristina della release (nuovo; "restore" è
// anch'esso "ripristina", disambiguato dal contesto), batch→gruppo (nuovo), Quick launch→avvio
// rapido (nuovo), one-shot agents→{{agents}} monouso (nuovo), display name→nome visualizzato
// (nuovo), subscription→sottoscrizione (nuovo), usage limit→limite di utilizzo (nuovo),
// Level → methods→Livello → metodi (nuovo).
